import{_ as s,o as e,c as n,am as l}from"./chunks/framework.CiF4W93w.js";const h=JSON.parse('{"title":"ES的服务安装","description":"","frontmatter":{"title":"ES的服务安装","excerpt":"摘要","date":"2024-12-24 00:47:30","updated":"2024-12-24 00:47:30"},"headers":[],"relativePath":"数据库/ElasticSearch/ES的服务安装/index.md","filePath":"数据库/ElasticSearch/ES的服务安装/index.md","lastUpdated":null}'),t={name:"数据库/ElasticSearch/ES的服务安装/index.md"};function i(p,a,c,o,u,d){return e(),n("div",null,[...a[0]||(a[0]=[l(`<p>首先明确一点的是： Elasticsearch是一个基于Lucene的搜索服务器。它提供了一个分布式的全文搜索引擎，基于restful web接口。</p><h4 id="服务下载与安装" tabindex="-1">服务下载与安装 <a class="header-anchor" href="#服务下载与安装" aria-label="Permalink to &quot;服务下载与安装&quot;">​</a></h4><p>一般下载：</p><ul><li>elasticsearch</li><li>中文分词器 analysis-ik <ul><li>安装中文分词器IKAnalyzer，注意下载与Elasticsearch对应的版本，下载地址：<a href="https://github.com/medcl/elasticsearch-analysis-ik/releases" target="_blank" rel="noreferrer">https://github.com/medcl/elasticsearch-analysis-ik/releases</a></li></ul></li><li>Kibana 访问Elasticsearch的客户端</li></ul><blockquote><p>Linux 下载</p></blockquote><ul><li>下载Elasticsearch<code>7.17.3</code>的docker镜像：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker pull elasticsearch:7.17.3</span></span></code></pre></div><ul><li>修改虚拟内存区域大小，否则会因为过小而无法启动:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl -w vm.max_map_count=262144</span></span></code></pre></div><ul><li>使用如下命令启动Elasticsearch服务，内存小的服务器可以通过<code>ES_JAVA_OPTS</code>来设置占用内存大小：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker run -p 9200:9200 -p 9300:9300 --name elasticsearch \\</span></span>
<span class="line"><span>-e &quot;discovery.type=single-node&quot; \\</span></span>
<span class="line"><span>-e &quot;cluster.name=elasticsearch&quot; \\</span></span>
<span class="line"><span>-e &quot;ES_JAVA_OPTS=-Xms512m -Xmx1024m&quot; \\</span></span>
<span class="line"><span>-v /mydata/elasticsearch/plugins:/usr/share/elasticsearch/plugins \\</span></span>
<span class="line"><span>-v /mydata/elasticsearch/data:/usr/share/elasticsearch/data \\</span></span>
<span class="line"><span>-d elasticsearch:7.17.3</span></span></code></pre></div><ul><li>启动时会发现<code>/usr/share/elasticsearch/data</code>目录没有访问权限，只需要修改<code>/mydata/elasticsearch/data</code>目录的权限，再重新启动即可；</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod 777 /mydata/elasticsearch/data/</span></span></code></pre></div><ul><li>安装中文分词器IKAnalyzer，注意下载与Elasticsearch对应的版本，下载地址：<a href="https://github.com/medcl/elasticsearch-analysis-ik/releases" target="_blank" rel="noreferrer">https://github.com/medcl/elasticsearch-analysis-ik/releases</a></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240728233023.png" alt="image.png"></p><ul><li>下载完成后解压到Elasticsearch的<code>/mydata/elasticsearch/plugins</code>目录下；</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240728233039.png" alt="image.png"></p><ul><li>重新启动服务：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker restart elasticsearch</span></span></code></pre></div><ul><li>开启防火墙：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>firewall-cmd --zone=public --add-port=9200/tcp --permanent</span></span>
<span class="line"><span>firewall-cmd --reload</span></span></code></pre></div><ul><li>访问会返回版本信息：<a href="http://192.168.3.101:9200" target="_blank" rel="noreferrer">http://192.168.3.101:9200</a></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;708f1d885c16&quot;,</span></span>
<span class="line"><span>  &quot;cluster_name&quot;: &quot;elasticsearch&quot;,</span></span>
<span class="line"><span>  &quot;cluster_uuid&quot;: &quot;mza51wT-QvaZ5R0NmE183g&quot;,</span></span>
<span class="line"><span>  &quot;version&quot;: {</span></span>
<span class="line"><span>    &quot;number&quot;: &quot;7.17.3&quot;,</span></span>
<span class="line"><span>    &quot;build_flavor&quot;: &quot;default&quot;,</span></span>
<span class="line"><span>    &quot;build_type&quot;: &quot;docker&quot;,</span></span>
<span class="line"><span>    &quot;build_hash&quot;: &quot;5ad023604c8d7416c9eb6c0eadb62b14e766caff&quot;,</span></span>
<span class="line"><span>    &quot;build_date&quot;: &quot;2022-04-19T08:11:19.070913226Z&quot;,</span></span>
<span class="line"><span>    &quot;build_snapshot&quot;: false,</span></span>
<span class="line"><span>    &quot;lucene_version&quot;: &quot;8.11.1&quot;,</span></span>
<span class="line"><span>    &quot;minimum_wire_compatibility_version&quot;: &quot;6.8.0&quot;,</span></span>
<span class="line"><span>    &quot;minimum_index_compatibility_version&quot;: &quot;6.0.0-beta1&quot;</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  &quot;tagline&quot;: &quot;You Know, for Search&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>Kibana 的下载</p></blockquote><ul><li>下载Kibana<code>7.17.3</code>的docker镜像：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker pull kibana:7.17.3</span></span></code></pre></div><ul><li>使用如下命令启动Kibana服务：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker run --name kibana -p 5601:5601 \\</span></span>
<span class="line"><span>--link elasticsearch:es \\</span></span>
<span class="line"><span>-e &quot;elasticsearch.hosts=http://es:9200&quot; \\</span></span>
<span class="line"><span>-d kibana:7.17.3</span></span></code></pre></div><ul><li>开启防火墙：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>firewall-cmd --zone=public --add-port=5601/tcp --permanent</span></span>
<span class="line"><span>firewall-cmd --reload</span></span></code></pre></div><ul><li>访问地址进行测试：<a href="http://192.168.3.101:5601" target="_blank" rel="noreferrer">http://192.168.3.101:5601</a></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240728233132.png" alt="image.png"></p><h4 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h4><ul><li>Near Realtime（近实时）：Elasticsearch是一个近乎实时的搜索平台，这意味着从索引文档到可搜索文档之间只有一个轻微的延迟(通常是一秒钟)。</li><li>Cluster（集群）：群集是一个或多个节点的集合，它们一起保存整个数据，并提供跨所有节点的联合索引和搜索功能。每个集群都有自己的唯一集群名称，节点通过名称加入集群。</li><li>Node（节点）：节点是指属于集群的单个Elasticsearch实例，存储数据并参与集群的索引和搜索功能。可以将节点配置为按集群名称加入特定集群，默认情况下，每个节点都设置为加入一个名为<code>elasticsearch</code>的群集。</li><li>Index（索引）：索引是一些具有相似特征的文档集合，类似于MySql中数据库的概念。</li><li>Type（类型）：类型是索引的逻辑类别分区，通常，为具有一组公共字段的文档类型，类似MySql中表的概念。<code>注意</code>：在Elasticsearch 6.0.0及更高的版本中，一个索引只能包含一个类型。</li><li>Document（文档）：文档是可被索引的基本信息单位，以JSON形式表示，类似于MySql中行记录的概念。</li><li>Shards（分片）：当索引存储大量数据时，可能会超出单个节点的硬件限制，为了解决这个问题，Elasticsearch提供了将索引细分为分片的概念。分片机制赋予了索引水平扩容的能力、并允许跨分片分发和并行化操作，从而提高性能和吞吐量。</li><li>Replicas（副本）：在可能出现故障的网络环境中，需要有一个故障切换机制，Elasticsearch提供了将索引的分片复制为一个或多个副本的功能，副本在某些节点失效的情况下提供高可用性。</li></ul>`,34)])])}const b=s(t,[["render",i]]);export{h as __pageData,b as default};
